<template><div class="wrap"><div class="box"><n-input v-model:value="input" type="textarea" :bordered="false" :autosize="{minRows:1,maxRows:8}" placeholder="向 Wisp 发送消息…" @keydown="key"/><div class="bar"><div class="selectors"><n-select v-model:value="modelKey" :options="modelOptions" size="small" class="model"/><n-select v-model:value="thinking" :options="thinkingOptions" size="small" class="thinking"/></div><button class="send" :disabled="!streaming&&(!input.trim()||!modelKey)" @click="streaming?chat.stop():chat.send()">{{streaming?'■':'↑'}}</button></div></div></div></template>
<script setup lang="ts">import { computed } from 'vue';import { NInput,NSelect } from 'naive-ui';import { storeToRefs } from 'pinia';import { useConnectionStore } from '../stores/connection';import { useChatStore } from '../stores/chat';const c=useConnectionStore(),chat=useChatStore();const {models}=storeToRefs(c);const {input,modelKey,thinking,thinkingLevels,streaming}=storeToRefs(chat);const modelOptions=computed(()=>models.value.map(m=>({label:`${m.name} · ${m.provider_name}`,value:m.key})));const labels:any={off:'关闭',on:'开启',low:'低',medium:'中',high:'高',auto:'自动',minimal:'最小'};const thinkingOptions=computed(()=>thinkingLevels.value.map(v=>({label:labels[v]||v,value:v})));function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!streaming.value)void chat.send()}}</script>
<style scoped>.wrap{padding:10px 20px 16px}.box{max-width:760px;margin:auto;border:1px solid var(--border);border-radius:18px;padding:12px 14px 10px}.box:focus-within{border-color:var(--pink)}.bar,.selectors{display:flex;align-items:center}.bar{justify-content:space-between;gap:8px}.selectors{gap:6px}.model{width:210px}.thinking{width:100px}.send{width:34px;height:34px;border:0;border-radius:50%;background:var(--pink);color:#fff;font-size:18px;cursor:pointer}.send:disabled{opacity:.35;cursor:not-allowed}@media(max-width:620px){.wrap{padding:8px}.model{width:155px}.thinking{width:82px}}</style>
